'use client'

import Link from 'next/link'
import { useRouter } from 'next/navigation'

export function BackLink() {
  const router = useRouter()

  const handleBack = (e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault()

    // Apply reverse transition direction for back navigation
    if (document.startViewTransition) {
      document.documentElement.classList.add('back-navigation')

      document.startViewTransition(() => {
        router.push('/')
      }).finished.finally(() => {
        document.documentElement.classList.remove('back-navigation')
      })
    } else {
      router.push('/')
    }
  }

  return (
    <Link href="/" className="back-link" onClick={handleBack}>
      ← Back to products
    </Link>
  )
}

